    input out0_ready,
    output reg [WIDTH-1:0] out1_data,
    output reg out1_valid,
    input out1_ready
);

always @(*) begin
    in_ready = out0_ready && out1_ready;
    out0_data = in_data;
    out0_valid = in_valid;
    out1_data = in_data;
    out1_valid = in_valid;
end

