module accumulator_core #(
    parameter DATA_WIDTH = 8
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire [DATA_WIDTH-1:0] data_in,
    input  wire                  valid_in,
    output wire                  ready_out,
    output reg  [DATA_WIDTH-1:0] data_out,
    output reg                   valid_out,
    input  wire                  ready_in
);

reg [DATA_WIDTH-1:0] accum;
reg accum_valid;

assign ready_out = ~accum_valid || (valid_out && ready_in);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accum <= {DATA_WIDTH{1'b0}};
        accum_valid <= 1'b0;
        data_out <= {DATA_WIDTH{1'b0}};
        valid_out <= 1'b0;
    end else begin
        // Input stage
        if (valid_in && ready_out) begin
            if (~accum_valid) begin
                accum <= data_in;
                accum_valid <= 1'b1;
            end else begin
                accum <= accum + data_in;
            end
        end
        // Output stage
        if (ready_in) begin
            if (accum_valid) begin
                data_out <= accum;
                valid_out <= 1'b1;
                accum_valid <= 1'b0;
                accum <= {DATA_WIDTH{1'b0}};
            end else begin
                valid_out <= 1'b0;
            end
        end else begin
            // hold output
        end
    end
end

endmodule

module skid_buffer #(
    parameter DATA_WIDTH = 8
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire [DATA_WIDTH-1:0] data_in,
    input  wire                  valid_in,
    output wire                  ready_out,
    output reg  [DATA_WIDTH-1:0] data_out,
    output reg                   valid_out,
    input  wire                  ready_in
);

reg skid_valid;
reg [DATA_WIDTH-1:0] skid_data;
wire skid_full = skid_valid;

assign ready_out = ~skid_full || (valid_out && ready_in);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        skid_valid <= 1'b0;
        valid_out <= 1'b0;
        data_out <= {DATA_WIDTH{1'b0}};
        skid_data <= {DATA_WIDTH{1'b0}};
    end else begin
        // Skid buffer logic
        if (valid_in && ready_out) begin
            if (!skid_full) begin
                // Store in skid
                skid_data <= data_in;
                skid_valid <= 1'b1;
            end else begin
                // Skid full, directly output if ready
                if (valid_out && ready_in) begin
                    data_out <= data_in;
                    // skid stays same
                end else begin
                    // No room, hold? Actually simple: just overwrite skid? 
                    // To be safe, we assume pipelined operation; for simplicity we treat as standard skid buffer
                    // Simplified: just pass through when possible
                end
            end
        end
        // Output stage
        if (ready_in) begin
            if (skid_valid) begin
                data_out <= skid_data;
                valid_out <= 1'b1;
                skid_valid <= 1'b0;
            end else begin
                valid_out <= 1'b0;
            end
        end else begin
            // hold
        end
    end
end

endmodule

module stream_join #(
    parameter DATA_WIDTH = 8
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire [DATA_WIDTH-1:0] data_in0,
    input  wire                  valid_in0,
    output reg                   ready_out0,
    input  wire [DATA_WIDTH-1:0] data_in1,
    input  wire                  valid_in1,
    output reg                   ready_out1,
    output reg  [DATA_WIDTH-1:0] data_out,
    output reg                   valid_out,
    input  wire                  ready_in
);

localparam IDLE = 2'd0;
localparam WAIT_BOTH = 2'd1;
localparam OUTPUT = 2'd2;

reg [1:0] state;
reg [1:0] next_state;

// State registers
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

// Next state logic and output
always @(*) begin
    next_state = state;
    ready_out0 = 1'b0;
    ready_out1 = 1'b0;
    data_out = {DATA_WIDTH{1'b0}};
    valid_out = 1'b0;
    case (state)
        IDLE: begin
            ready_out0 = 1'b1;
            ready_out1 = 1'b1;
            if (valid_in0 || valid_in1) begin
                next_state = WAIT_BOTH;
            end
        end
        WAIT_BOTH: begin
            ready_out0 = 1'b1;
            ready_out1 = 1'b1;
            if (valid_in0 && valid_in1) begin
                next_state = OUTPUT;
            end
        end
        OUTPUT: begin
            if (ready_in) begin
                data_out = data_in0 + data_in1;
                valid_out = 1'b1;
                next_state = IDLE;
            end else begin
                // hold output until ready
                data_out = data_in0 + data_in1;
                valid_out = 1'b1;
                ready_out0 = 1'b0;
                ready_out1 = 1'b0;
            end
        end
        default: next_state = IDLE;
    endcase
end

endmodule

module stream_stage #(
    parameter DATA_WIDTH = 8
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire [DATA_WIDTH-1:0] data_in,
    input  wire                  valid_in,
    output wire                  ready_out,
    output reg  [DATA_WIDTH-1:0] data_out,
    output reg                   valid_out,
    input  wire                  ready_in
);

reg [DATA_WIDTH-1:0] stage_data;
reg stage_valid;

assign ready_out = ~stage_valid || (valid_out && ready_in);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage_data <= {DATA_WIDTH{1'b0}};
        stage_valid <= 1'b0;
        data_out <= {DATA_WIDTH{1'b0}};
        valid_out <= 1'b0;
    end else begin
        // Load stage
        if (valid_in && ready_out) begin
            stage_data <= data_in;
            stage_valid <= 1'b1;
        end
        // Output handshake
        if (ready_in) begin
            if (stage_valid) begin
                data_out <= stage_data;
                valid_out <= 1'b1;
                stage_valid <= 1'b0;
            end else begin
                valid_out <= 1'b0;
            end
        end else begin
            // hold
        end
    end
end

endmodule

