module skid_buffer #(parameter WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [WIDTH-1:0] out_data,
    input wire out_ready
);
    reg skid_valid;
    reg [WIDTH-1:0] skid_data;

    assign in_ready = !skid_valid || out_ready;
    assign out_valid = in_valid || skid_valid;
    assign out_data = skid_valid ? skid_data : in_data;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            skid_valid <= 1'b0;
            skid_data <= 0;
        end else begin
            if (in_ready && in_valid) begin
                if (out_ready) begin
                    skid_valid <= 1'b0;
                end else begin
                    skid_valid <= 1'b1;
                    skid_data <= in_data;
                end
            end else if (skid_valid && out_ready) begin
                skid_valid <= 1'b0;
            end
        end
    end
endmodule

module stream_fork #(parameter WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out0_valid,
    output wire [WIDTH-1:0] out0_data,
    input wire out0_ready,
    output wire out1_valid,
    output wire [WIDTH-1:0] out1_data,
    input wire out1_ready
);
    reg busy;
    reg [WIDTH-1:0] data_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0;
            data_reg <= 0;
        end else begin
            if (busy) begin
                if (out0_ready && out1_ready) begin
                    busy <= 1'b0;
                end
            end else begin
                if (in_valid) begin
                    busy <= 1'b1;
                    data_reg <= in_data;
                end
            end
        end
    end

    assign in_ready = !busy;
    assign out0_valid = busy;
    assign out0_data = data_reg;
    assign out1_valid = busy;
    assign out1_data = data_reg;
endmodule

module stream_stage #(parameter WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [WIDTH-1:0] out_data,
    input wire out_ready
);
    reg out_valid_reg;
    reg [WIDTH-1:0] out_data_reg;

    wire fire = in_valid && in_ready;
    assign in_ready = !out_valid_reg || out_ready;
    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid_reg <= 1'b0;
            out_data_reg <= 0;
        end else begin
            if (fire) begin
                out_valid_reg <= 1'b1;
                out_data_reg <= in_data;
            end else if (out_ready && out_valid_reg) begin
                out_valid_reg <= 1'b0;
            end
        end
    end
endmodule

module tb_top;
    reg clk;
    reg rst_n;
    reg in_valid;
    reg [7:0] in_data;
    wire in_ready;
    wire out0_valid;
    wire [7:0] out0_data;
    reg out0_ready;
    wire out1_valid;
    wire [7:0] out1_data;
    reg out1_ready;

    top dut (.*);

    parameter NUM_TRANS = 200;
    reg [7:0] expected [0:NUM_TRANS-1];
    integer send_idx, recv0_idx, recv1_idx;
    integer i;

    // Clock
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Reset and main stimulus
    initial begin
        rst_n = 0;
        in_valid = 0;
        in_data = 0;
        out0_ready = 1;
        out1_ready = 1;
        send_idx = 0;
        recv0_idx = 0;
        recv1_idx = 0;

        // Populate expected data with random values
        for (i = 0; i < NUM_TRANS; i = i + 1) begin
            expected[i] = $random & 8'hFF;
        end

        // De-assert reset after 10 cycles
        repeat (10) @(negedge clk);
        rst_n = 1;

        fork
            // Send transactions
            begin : send_proc
                for (send_idx = 0; send_idx < NUM_TRANS; send_idx = send_idx + 1) begin
                    // Wait for in_ready
                    while (!in_ready) @(negedge clk);
                    // Drive valid and data on negedge
                    @(negedge clk);
                    in_valid = 1;
                    in_data = expected[send_idx];
                    // Wait for handshake to be sampled (posedge)
                    @(posedge clk);
                    // De-assert valid on next negedge
                    @(negedge clk);
                    in_valid = 0;
                end
            end

            // Receive on out0
            begin : recv0_proc
                while (recv0_idx < NUM_TRANS) begin
                    @(negedge clk);
                    if (out0_valid && out0_ready) begin
                        if (out0_data !== expected[recv0_idx]) begin
                            $display("TEST_FAIL: out0 data mismatch at index %d: expected %h, got %h", recv0_idx, expected[recv0_idx], out0_data);
                            $finish;
                        end
                        recv0_idx = recv0_idx + 1;
                    end
                end
            end

            // Receive on out1
            begin : recv1_proc
                while (recv1_idx < NUM_TRANS) begin
                    @(negedge clk);
                    if (out1_valid && out1_ready) begin
                        if (out1_data !== expected[recv1_idx]) begin
                            $display("TEST_FAIL: out1 data mismatch at index %d: expected %h, got %h", recv1_idx, expected[recv1_idx], out1_data);
                            $finish;
                        end
                        recv1_idx = recv1_idx + 1;
                    end
                end
            end

            // Randomly deassert ready to exercise backpressure
            begin : ready_proc
                while (send_idx < NUM_TRANS || recv0_idx < NUM_TRANS || recv1_idx < NUM_TRANS) begin
                    @(negedge clk);
                    out0_ready = $random % 2;
                    out1_ready = $random % 2;
                end
            end
        join

        if (recv0_idx == NUM_TRANS && recv1_idx == NUM_TRANS)
            $display("TEST_PASS");
        else
            $display("TEST_FAIL: Incomplete reception");
        $finish;
    end

    // Timeout watchdog
    integer timeout;
    initial begin
        timeout = 0;
        while (timeout < 50000) begin
            @(posedge clk);
            timeout = timeout + 1;
        end
        $display("TEST_FAIL: Timeout");
        $finish;
    end
endmodule

