module skid_buffer (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
    reg out_valid_r;
    reg out_valid_buf;
    reg [DATA_WIDTH-1:0] out_data_r;
    reg [DATA_WIDTH-1:0] out_data_buf;

    assign in_ready = !out_valid_buf;
    assign out_valid = out_valid_r;
    assign out_data   = out_data_r;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        out_valid_r   <= 1'b0;
        out_valid_buf <= 1'b0;
      end else begin
        // output handshake
        if (out_ready && out_valid_r) begin
          if (out_valid_buf) begin
            out_valid_r <= 1'b1;
            out_data_r  <= out_data_buf;
            out_valid_buf <= 1'b0;
          end else begin
            out_valid_r <= 1'b0;
          end
        end
        // input handshake
        if (in_valid && in_ready) begin
          if (!out_valid_r) begin
            out_valid_r <= 1'b1;
            out_data_r  <= in_data;
          end else begin
            out_valid_buf <= 1'b1;
            out_data_buf  <= in_data;
          end
        end
      end
    end
endmodule

module stream_fork (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out0_valid,
    output wire [DATA_WIDTH-1:0] out0_data,
    input wire out0_ready,
    output wire out1_valid,
    output wire [DATA_WIDTH-1:0] out1_data,
    input wire out1_ready
);
    assign in_ready   = out0_ready && out1_ready;
    assign out0_valid = in_valid;
    assign out0_data  = in_data;
    assign out1_valid = in_valid;
    assign out1_data  = in_data;
endmodule

module stream_stage (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
    reg out_valid_r;
    reg [DATA_WIDTH-1:0] out_data_r;

    assign out_valid = out_valid_r;
    assign out_data = out_data_r;
    assign in_ready = !out_valid_r || out_ready;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        out_valid_r <= 1'b0;
      end else begin
        if (in_ready) begin
          out_valid_r <= in_valid;
          out_data_r  <= in_data;
        end
      end
    end
endmodule

