module baud_tick_gen #(
    parameter CLK_FREQ = 100000000,
    parameter BAUD_RATE = 115200
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    output reg tick
);
    localparam DIVISOR = CLK_FREQ / BAUD_RATE;
    reg [31:0] counter;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            tick <= 0;
        end else if (en) begin
            if (counter == DIVISOR - 1) begin
                counter <= 0;
                tick <= 1;
            end else begin
                counter <= counter + 1;
                tick <= 0;
            end
        end else begin
            counter <= 0;
            tick <= 0;
        end
    end
endmodule

module uart_tx_core (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] data,
    input wire baud_tick,
    output reg tx,
    output reg busy
);
    localparam IDLE = 0,
               START = 1,
               DATA = 2,
               STOP = 3;
    reg [1:0] state, next_state;
    reg [3:0] bit_index;
    reg [7:0] shift_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            tx <= 1;
            busy <= 0;
            bit_index <= 0;
            shift_reg <= 0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    tx <= 1;
                    busy <= 0;
                    if (start) begin
                        shift_reg <= data;
                        bit_index <= 0;
                    end
                end
                START: begin
                    tx <= 0;
                    busy <= 1;
                end
                DATA: begin
                    tx <= shift_reg[0];
                    if (baud_tick) begin
                        shift_reg <= {1'b0, shift_reg[7:1]};
                        bit_index <= bit_index + 1;
                    end
                    busy <= 1;
                end
                STOP: begin
                    tx <= 1;
                    busy <= 1;
                end
            endcase
        end
    end
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = START;
            START: if (baud_tick) next_state = DATA;
            DATA: if (baud_tick) begin
                if (bit_index == 7) next_state = STOP;
                else next_state = DATA;
            end
            STOP: if (baud_tick) next_state = IDLE;
        endcase
    end
endmodule

