// Accumulator core: adds input to internal register modulo 256
module accumulator_core #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in_valid,
  output wire                in_ready,
  input  wire [DATA_WIDTH-1:0] in_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  reg [DATA_WIDTH-1:0] acc_reg;
  reg acc_valid;

  wire transfer_in = in_valid & in_ready;
  wire transfer_out = acc_valid & out_ready;

  assign in_ready = out_ready | ~acc_valid;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      acc_reg <= 0;
      acc_valid <= 1'b0;
    end else begin
      if (transfer_out) begin
        acc_valid <= 1'b0;
      end
      if (transfer_in & (transfer_out | ~acc_valid)) begin
        acc_reg <= acc_reg + in_data;
        acc_valid <= 1'b1;
      end
    end
  end

  assign out_valid = acc_valid;
  assign out_data = acc_reg;

endmodule

`timescale 1ns / 1ps

// Skid buffer: enables one word of storage to decouple handshake
module skid_buffer #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in_valid,
  output wire                in_ready,
  input  wire [DATA_WIDTH-1:0] in_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  // Skid buffer implementation
  reg skid_valid;
  reg [DATA_WIDTH-1:0] skid_data;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      skid_valid <= 1'b0;
    end else begin
      if (in_ready) begin
        skid_valid <= 1'b0;
      end else if (in_valid) begin
        skid_valid <= 1'b1;
        skid_data <= in_data;
      end
    end
  end

  // combinational
  assign in_ready = ~skid_valid | out_ready;
  assign out_valid = skid_valid | (in_valid & ~skid_valid);
  assign out_data = (skid_valid) ? skid_data : in_data;

endmodule

`timescale 1ns / 1ps

// Stream join: waits for both inputs valid, then outputs sum modulo 256
module stream_join #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in0_valid,
  output wire                in0_ready,
  input  wire [DATA_WIDTH-1:0] in0_data,
  input  wire                in1_valid,
  output wire                in1_ready,
  input  wire [DATA_WIDTH-1:0] in1_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  // Simple implementation: combinational sum when both valid
  assign in0_ready = out_ready | ~out_valid;
  assign in1_ready = out_ready | ~out_valid;
  // Need registered output for proper handshake with backpressure
  reg [DATA_WIDTH-1:0] sum_reg;
  reg sum_valid;

  wire both_valid = in0_valid & in1_valid;
  wire transfer = sum_valid & out_ready;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sum_valid <= 1'b0;
      sum_reg <= 0;
    end else begin
      if (transfer) begin
        sum_valid <= 1'b0;
      end
      if (both_valid & (transfer | ~sum_valid)) begin
        sum_valid <= 1'b1;
        sum_reg <= in0_data + in1_data;
      end
    end
  end

  assign out_valid = sum_valid;
  assign out_data = sum_reg;

endmodule

`timescale 1ns / 1ps

// Pipeline stage with valid-ready handshake
module stream_stage #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in_valid,
  output wire                in_ready,
  input  wire [DATA_WIDTH-1:0] in_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  reg [DATA_WIDTH-1:0] pipe_reg;
  reg pipe_valid;

  wire transfer_in = in_valid & in_ready;
  wire transfer_out = pipe_valid & out_ready;

  assign in_ready = out_ready | ~pipe_valid;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pipe_reg <= 0;
      pipe_valid <= 1'b0;
    end else begin
      if (transfer_out) begin
        pipe_valid <= 1'b0;
      end
      if (transfer_in & (transfer_out | ~pipe_valid)) begin
        pipe_reg <= in_data;
        pipe_valid <= 1'b1;
      end
    end
  end

  assign out_valid = pipe_valid;
  assign out_data = pipe_reg;

endmodule

`timescale 1ns / 1ps

module top #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in0_valid,
  output wire                in0_ready,
  input  wire [DATA_WIDTH-1:0] in0_data,
  input  wire                in1_valid,
  output wire                in1_ready,
  input  wire [DATA_WIDTH-1:0] in1_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  // Internal wires
  wire [DATA_WIDTH-1:0] buffer0_out_data;
  wire buffer0_out_valid;
  wire [DATA_WIDTH-1:0] buffer1_out_data;
  wire buffer1_out_valid;
  wire [DATA_WIDTH-1:0] join_out_data;
  wire join_out_valid;
  wire join_in0_ready;
  wire join_in1_ready;
  wire [DATA_WIDTH-1:0] acc_out_data;
  wire acc_out_valid;
  wire acc_in_ready;
  wire stage_in_ready;

  // Instantiate skid_buffer for input 0
  skid_buffer #(
    .DATA_WIDTH(DATA_WIDTH)
  ) in0_buffer (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in0_valid),
    .in_ready(in0_ready),
    .in_data(in0_data),
    .out_valid(buffer0_out_valid),
    .out_ready(join_in0_ready),
    .out_data(buffer0_out_data)
  );

  // Instantiate skid_buffer for input 1
  skid_buffer #(
    .DATA_WIDTH(DATA_WIDTH)
  ) in1_buffer (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in1_valid),
    .in_ready(in1_ready),
    .in_data(in1_data),
    .out_valid(buffer1_out_valid),
    .out_ready(join_in1_ready),
    .out_data(buffer1_out_data)
  );

  // Instantiate stream_join
  stream_join #(
    .DATA_WIDTH(DATA_WIDTH)
  ) join_core (
    .clk(clk),
    .rst_n(rst_n),
    .in0_valid(buffer0_out_valid),
    .in0_ready(join_in0_ready),
    .in0_data(buffer0_out_data),
    .in1_valid(buffer1_out_valid),
    .in1_ready(join_in1_ready),
    .in1_data(buffer1_out_data),
    .out_valid(join_out_valid),
    .out_ready(acc_in_ready),
    .out_data(join_out_data)
  );

  // Instantiate accumulator_core
  accumulator_core #(
    .DATA_WIDTH(DATA_WIDTH)
  ) accumulator (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(join_out_valid),
    .in_ready(acc_in_ready),
    .in_data(join_out_data),
    .out_valid(acc_out_valid),
    .out_ready(stage_in_ready),
    .out_data(acc_out_data)
  );

  // Instantiate stream_stage
  stream_stage #(
    .DATA_WIDTH(DATA_WIDTH)
  ) out_stage (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(acc_out_valid),
    .in_ready(stage_in_ready),
    .in_data(acc_out_data),
    .out_valid(out_valid),
    .out_ready(out_ready),
    .out_data(out_data)
  );

endmodule

