        .DATA_WIDTH(8)
    ) accumulator (
        .clk(clk),
        .reset_n(reset_n),
        .in_valid(join_out_valid),
        .in_ready(join_out_ready),
        .in_data(join_out_data),
        .out_valid(acc_out_valid),
        .out_ready(acc_out_ready),
        .out_data(acc_out_data)
    );

