module accumulator_core #(parameter W=8) (
  input clk, rst_n,
  input [W-1:0] data_in,
  input valid_in,
  output wire ready_out,
  output reg [W-1:0] data_out,
  output reg valid_out,
  input ready_in
);

  reg [W-1:0] accum;

  assign ready_out = !valid_out || ready_in;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      accum <= 0;
      valid_out <= 0;
      data_out <= 0;
    end else begin
      if (ready_in && valid_out) begin
        valid_out <= 0;
      end
      if (valid_in && ready_out) begin
        accum <= accum + data_in;
        data_out <= accum + data_in;
        valid_out <= 1;
      end
    end
  end
endmodule

module skid_buffer #(parameter W=8) (
  input clk, rst_n,
  input [W-1:0] data_in,
  input valid_in,
  output wire ready_out,
  output reg [W-1:0] data_out,
  output reg valid_out,
  input ready_in
);

  reg buf_full;

  assign ready_out = !buf_full || ready_in;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      buf_full <= 0;
      data_out <= 0;
      valid_out <= 0;
    end else begin
      if (ready_in && valid_out) begin
        valid_out <= 0;
        buf_full <= 0;
      end
      if (valid_in && ready_out) begin
        data_out <= data_in;
        valid_out <= 1;
        buf_full <= 1;
      end
    end
  end
endmodule

module stream_join #(parameter W=8) (
  input clk, rst_n,
  input [W-1:0] input0_data,
  input input0_valid,
  output wire input0_ready,
  input [W-1:0] input1_data,
  input input1_valid,
  output wire input1_ready,
  output reg [W-1:0] output_data,
  output reg output_valid,
  input output_ready
);

  reg [W-1:0] buf0, buf1;
  reg buf0_valid, buf1_valid;
  wire both_valid = buf0_valid && buf1_valid;
  wire output_transfer = both_valid && output_ready;

  assign input0_ready = !buf0_valid || (output_transfer && buf1_valid);
  assign input1_ready = !buf1_valid || (output_transfer && buf0_valid);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      buf0_valid <= 0;
      buf1_valid <= 0;
      output_valid <= 0;
      output_data <= 0;
    end else begin
      if (output_transfer) begin
        output_valid <= 1;
        output_data <= buf0 + buf1;
        buf0_valid <= 0;
        buf1_valid <= 0;
      end else begin
        output_valid <= 0;
      end

      if (input0_valid && input0_ready) begin
        buf0 <= input0_data;
        buf0_valid <= 1;
      end
      if (input1_valid && input1_ready) begin
        buf1 <= input1_data;
        buf1_valid <= 1;
      end
    end
  end
endmodule

module stream_stage #(parameter W=8) (
  input clk, rst_n,
  input [W-1:0] data_in,
  input valid_in,
  output wire ready_out,
  output reg [W-1:0] data_out,
  output reg valid_out,
  input ready_in
);

  assign ready_out = !valid_out || ready_in;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_out <= 0;
      data_out <= 0;
    end else begin
      if (ready_in && valid_out) begin
        valid_out <= 0;
      end
      if (valid_in && ready_out) begin
        data_out <= data_in;
        valid_out <= 1;
      end
    end
  end
endmodule

module top #(parameter DATA_WIDTH=8) (
  input clk, rst_n,
  input [DATA_WIDTH-1:0] in0_data,
  input in0_valid,
  output in0_ready,
  input [DATA_WIDTH-1:0] in1_data,
  input in1_valid,
  output in1_ready,
  output [DATA_WIDTH-1:0] out_data,
  output out_valid,
  input out_ready
);

  wire [DATA_WIDTH-1:0] buf0_out, buf1_out;
  wire buf0_valid, buf1_valid;
  wire buf0_ready, buf1_ready;

  skid_buffer #(.W(DATA_WIDTH)) in0_buffer (
    .clk(clk), .rst_n(rst_n),
    .data_in(in0_data), .valid_in(in0_valid), .ready_out(in0_ready),
    .data_out(buf0_out), .valid_out(buf0_valid), .ready_in(buf0_ready)
  );

  skid_buffer #(.W(DATA_WIDTH)) in1_buffer (
    .clk(clk), .rst_n(rst_n),
    .data_in(in1_data), .valid_in(in1_valid), .ready_out(in1_ready),
    .data_out(buf1_out), .valid_out(buf1_valid), .ready_in(buf1_ready)
  );

  wire [DATA_WIDTH-1:0] join_out;
  wire join_valid;
  wire join_ready;

  stream_join #(.W(DATA_WIDTH)) join_core (
    .clk(clk), .rst_n(rst_n),
    .input0_data(buf0_out), .input0_valid(buf0_valid), .input0_ready(buf0_ready),
    .input1_data(buf1_out), .input1_valid(buf1_valid), .input1_ready(buf1_ready),
    .output_data(join_out), .output_valid(join_valid), .output_ready(join_ready)
  );

  wire [DATA_WIDTH-1:0] acc_out;
  wire acc_valid;
  wire acc_ready;

  accumulator_core #(.W(DATA_WIDTH)) accumulator (
    .clk(clk), .rst_n(rst_n),
    .data_in(join_out), .valid_in(join_valid), .ready_out(join_ready),
    .data_out(acc_out), .valid_out(acc_valid), .ready_in(acc_ready)
  );

  wire [DATA_WIDTH-1:0] stage_out;
  wire stage_valid;

  stream_stage #(.W(DATA_WIDTH)) out_stage (
    .clk(clk), .rst_n(rst_n),
    .data_in(acc_out), .valid_in(acc_valid), .ready_out(acc_ready),
    .data_out(stage_out), .valid_out(stage_valid), .ready_in(out_ready)
  );

  assign out_data = stage_out;
  assign out_valid = stage_valid;

endmodule

`timescale 1ns/1ps
module tb;
  reg clk, rst_n;
  reg [7:0] in0_data, in1_data;
  reg in0_valid, in1_valid;
  wire in0_ready, in1_ready;
  wire [7:0] out_data;
  wire out_valid;
  reg out_ready;

  integer i;
  reg [7:0] expected;
  integer timeout;

  top #(.DATA_WIDTH(8)) dut (
    .clk(clk), .rst_n(rst_n),
    .in0_data(in0_data), .in0_valid(in0_valid), .in0_ready(in0_ready),
    .in1_data(in1_data), .in1_valid(in1_valid), .in1_ready(in1_ready),
    .out_data(out_data), .out_valid(out_valid), .out_ready(out_ready)
  );

  always #5 clk = ~clk;

  initial begin
    clk = 0;
    rst_n = 0;
    in0_valid = 0;
    in1_valid = 0;
    out_ready = 0;
    in0_data = 0;
    in1_data = 0;
    #10;
    rst_n = 1;
    #10;
    out_ready = 1;
    in0_data = 8'd1;
    in1_data = 8'd2;
    in0_valid = 1;
    in1_valid = 1;

    timeout = 0;
    for (i = 0; i < 4; i = i + 1) begin
      expected = 3 * (i + 1);
      wait(out_valid);
      @(posedge clk) #1;
      if (out_data !== expected) begin
        $display("TEST_FAIL: output mismatch at transfer %0d: expected %0d, got %0d", i, expected, out_data);
        $finish;
      end
      @(posedge clk);
    end
    $display("TEST_PASS");
    $finish;
  end

  initial begin
    #1000;
    $display("TEST_FAIL: timeout");
    $finish;
  end
endmodule

