module accumulator_core #(
    parameter DATA_WIDTH = 8
)(
    input  wire clk,
    input  wire rst_n,
    input  wire valid_in,
    output wire ready_in,
    input  wire [DATA_WIDTH-1:0] data_in,
    output wire valid_out,
    input  wire ready_out,
    output wire [DATA_WIDTH-1:0] data_out
);

    reg [DATA_WIDTH-1:0] accumulator_reg;
    reg acc_valid_reg;

    assign ready_in = !acc_valid_reg || ready_out;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            accumulator_reg <= 0;
            acc_valid_reg <= 1'b0;
        end else begin
            if (valid_in && ready_in) begin
                accumulator_reg <= accumulator_reg + data_in;
                acc_valid_reg <= 1'b1;
            end else if (acc_valid_reg && ready_out) begin
                if (!valid_in || !ready_in) begin
                    acc_valid_reg <= 1'b0;
                end
            end
        end
    end

    assign valid_out = acc_valid_reg;
    assign data_out = accumulator_reg;

endmodule

module skid_buffer #(
    parameter DATA_WIDTH = 8
)(
    input  wire clk,
    input  wire rst_n,
    input  wire valid_in,
    output wire ready_in,
    input  wire [DATA_WIDTH-1:0] data_in,
    output wire valid_out,
    input  wire ready_out,
    output wire [DATA_WIDTH-1:0] data_out
);

    reg skid_valid;
    reg [DATA_WIDTH-1:0] skid_data;

    assign ready_in = !skid_valid || ready_out;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            skid_valid <= 1'b0;
        end else begin
            if (valid_in && ready_in) begin
                skid_data <= data_in;
                skid_valid <= 1'b1;
            end else if (ready_out && skid_valid) begin
                skid_valid <= 1'b0;
            end
        end
    end

    assign valid_out = skid_valid;
    assign data_out = skid_data;

endmodule

module stream_join #(
    parameter DATA_WIDTH = 8
)(
    input  wire clk,
    input  wire rst_n,
    input  wire in0_valid,
    output wire in0_ready,
    input  wire [DATA_WIDTH-1:0] in0_data,
    input  wire in1_valid,
    output wire in1_ready,
    input  wire [DATA_WIDTH-1:0] in1_data,
    output wire out_valid,
    input  wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);

    reg out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;
    wire both_valid = in0_valid && in1_valid;
    wire accept = out_valid_reg && out_ready; // downstream accepts
    wire load = both_valid && (accept || !out_valid_reg); // load new data when we can

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid_reg <= 1'b0;
            out_data_reg <= 0;
        end else begin
            if (load) begin
                out_data_reg <= in0_data + in1_data;
                out_valid_reg <= 1'b1;
            end else if (accept) begin
                out_valid_reg <= 1'b0;
            end
        end
    end

    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;
    assign in0_ready = !out_valid_reg || out_ready;
    assign in1_ready = !out_valid_reg || out_ready;

endmodule

module stream_stage #(
    parameter DATA_WIDTH = 8
)(
    input  wire clk,
    input  wire rst_n,
    input  wire valid_in,
    output wire ready_in,
    input  wire [DATA_WIDTH-1:0] data_in,
    output wire valid_out,
    input  wire ready_out,
    output wire [DATA_WIDTH-1:0] data_out
);

    reg valid_reg;
    reg [DATA_WIDTH-1:0] data_reg;

    assign ready_in = !valid_reg || ready_out;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_reg <= 1'b0;
        end else begin
            if (ready_in) begin
                if (valid_in) begin
                    valid_reg <= 1'b1;
                    data_reg <= data_in;
                end else begin
                    valid_reg <= 1'b0;
                end
            end else begin
                // stalled: keep current state
            end
        end
    end

    assign valid_out = valid_reg;
    assign data_out = data_reg;

endmodule

module top #(
    parameter DATA_WIDTH = 8
)(
    input  wire clk,
    input  wire rst_n,
    input  wire in0_valid,
    output wire in0_ready,
    input  wire [DATA_WIDTH-1:0] in0_data,
    input  wire in1_valid,
    output wire in1_ready,
    input  wire [DATA_WIDTH-1:0] in1_data,
    output wire out_valid,
    input  wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);

    wire [DATA_WIDTH-1:0] in0_buf_data;
    wire in0_buf_valid;
    wire in0_buf_ready;
    wire [DATA_WIDTH-1:0] in1_buf_data;
    wire in1_buf_valid;
    wire in1_buf_ready;

    wire [DATA_WIDTH-1:0] join_data;
    wire join_valid;
    wire join_ready;

    wire [DATA_WIDTH-1:0] acc_data;
    wire acc_valid;
    wire acc_ready;

    // Input skid buffers
    skid_buffer #(
        .DATA_WIDTH(DATA_WIDTH)
    ) in0_buffer (
        .clk(clk),
        .rst_n(rst_n),
        .valid_in(in0_valid),
        .ready_in(in0_ready),
        .data_in(in0_data),
        .valid_out(in0_buf_valid),
        .ready_out(in0_buf_ready),
        .data_out(in0_buf_data)
    );

    skid_buffer #(
        .DATA_WIDTH(DATA_WIDTH)
    ) in1_buffer (
        .clk(clk),
        .rst_n(rst_n),
        .valid_in(in1_valid),
        .ready_in(in1_ready),
        .data_in(in1_data),
        .valid_out(in1_buf_valid),
        .ready_out(in1_buf_ready),
        .data_out(in1_buf_data)
    );

    // Stream join
    stream_join #(
        .DATA_WIDTH(DATA_WIDTH)
    ) join_core (
        .clk(clk),
        .rst_n(rst_n),
        .in0_valid(in0_buf_valid),
        .in0_ready(in0_buf_ready),
        .in0_data(in0_buf_data),
        .in1_valid(in1_buf_valid),
        .in1_ready(in1_buf_ready),
        .in1_data(in1_buf_data),
        .out_valid(join_valid),
        .out_ready(join_ready),
        .out_data(join_data)
    );

    // Accumulator
    accumulator_core #(
        .DATA_WIDTH(DATA_WIDTH)
    ) accumulator (
        .clk(clk),
        .rst_n(rst_n),
        .valid_in(join_valid),
        .ready_in(join_ready),
        .data_in(join_data),
        .valid_out(acc_valid),
        .ready_out(acc_ready),
        .data_out(acc_data)
    );

    // Output pipeline stage
    stream_stage #(
        .DATA_WIDTH(DATA_WIDTH)
    ) out_stage (
        .clk(clk),
        .rst_n(rst_n),
        .valid_in(acc_valid),
        .ready_in(acc_ready),
        .data_in(acc_data),
        .valid_out(out_valid),
        .ready_out(out_ready),
        .data_out(out_data)
    );

endmodule

`timescale 1ns/1ps

module tb_top;

    parameter DATA_WIDTH = 8;

    reg clk;
    reg rst_n;

    reg in0_valid;
    wire in0_ready;
    reg [DATA_WIDTH-1:0] in0_data;
    reg in1_valid;
    wire in1_ready;
    reg [DATA_WIDTH-1:0] in1_data;

    wire out_valid;
    reg out_ready;
    wire [DATA_WIDTH-1:0] out_data;

    // DUT
    top #(
        .DATA_WIDTH(DATA_WIDTH)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .in0_valid(in0_valid),
        .in0_ready(in0_ready),
        .in0_data(in0_data),
        .in1_valid(in1_valid),
        .in1_ready(in1_ready),
        .in1_data(in1_data),
        .out_valid(out_valid),
        .out_ready(out_ready),
        .out_data(out_data)
    );

    // Clock generation
    always #5 clk = ~clk;

    // Test stimulus and checker
    integer cycle_count;
    integer i;
    reg [DATA_WIDTH-1:0] expected_out [0:2];
    reg [DATA_WIDTH-1:0] seq0 [0:2];
    reg [DATA_WIDTH-1:0] seq1 [0:2];
    reg test_pass;
    integer num_packets;

    initial begin
        $display("Starting testbench...");
        test_pass = 1;
        num_packets = 3;

        // Initialize sequences
        seq0[0] = 8'd1;
        seq0[1] = 8'd2;
        seq0[2] = 8'd3;
        seq1[0] = 8'd4;
        seq1[1] = 8'd5;
        seq1[2] = 8'd6;

        // Expected outputs after accumulation (sums accumulate)
        expected_out[0] = 8'd1 + 8'd4; // 5
        expected_out[1] = expected_out[0] + 8'd2 + 8'd5; // 5+2+5=12
        expected_out[2] = expected_out[1] + 8'd3 + 8'd6; // 12+3+6=21

        // Initialize signals
        clk = 0;
        rst_n = 0;
        in0_valid = 0;
        in1_valid = 0;
        out_ready = 1; // ready to absorb
        in0_data = 0;
        in1_data = 0;

        // Reset
        #15 rst_n = 1;
        #20;

        // Basic test: drive stimulus and check each output
        for (i = 0; i < num_packets; i = i + 1) begin
            @(negedge clk);
            in0_valid = 1;
            in1_valid = 1;
            in0_data = seq0[i];
            in1_data = seq1[i];
            @(posedge clk);
            // Wait for output valid
            wait(out_valid);
            // Small delay to allow data to settle
            #1;
            if (out_data !== expected_out[i]) begin
                $display("TEST_FAIL at packet %0d: expected %0d, got %0d", i, expected_out[i], out_data);
                test_pass = 0;
            end else begin
                $display("Packet %0d OK: expected %0d, got %0d", i, expected_out[i], out_data);
            end
            // Withdraw valid on next negedge
            @(negedge clk);
            in0_valid = 0;
            in1_valid = 0;
        end

        // Additional backpressure test
        $display("Backpressure test...");
        // Reset
        @(negedge clk);
        rst_n = 0;
        #20 rst_n = 1;
        #20;

        // Backpressure test with full pipeline clearing
        for (i = 0; i < num_packets; i = i + 1) begin
            @(negedge clk);
            in0_valid = 1;
            in1_valid = 1;
            in0_data = seq0[i];
            in1_data = seq1[i];
            // Hold out_ready low initially
            out_ready = 0;
            // After some cycles, assert out_ready
            if (i == 0) begin
                #30 out_ready = 1;
            end else begin
                #15 out_ready = 1;
            end
            @(posedge clk);
            // Wait for output valid
            wait(out_valid);
            #1;
            if (out_data !== expected_out[i]) begin
                $display("TEST_FAIL backpressure packet %0d: expected %0d, got %0d", i, expected_out[i], out_data);
                test_pass = 0;
            end else begin
                $display("Backpressure packet %0d OK", i);
            end
            @(negedge clk);
            in0_valid = 0;
            in1_valid = 0;
            out_ready = 0; // re-assert backpressure for next
        end

        #100;

        if (test_pass) begin
            $display("TEST_PASS");
        end else begin
            $display("TEST_FAIL");
        end

        $finish;
    end

endmodule

