// Accumulator that adds input data to internal register on each valid transfer
`timescale 1ns / 1ps

module accumulator_core #(
    parameter DATA_WIDTH = 8
) (
    input  wire                        clk,
    input  wire                        reset_n,
    input  wire [DATA_WIDTH-1:0]       data_in,
    input  wire                        valid_in,
    output wire                        ready_out,
    output wire [DATA_WIDTH-1:0]       data_out,
    output wire                        valid_out,
    input  wire                        ready_in
);

    reg [DATA_WIDTH-1:0] acc_reg;
    reg                   valid_reg;

    wire load   = valid_in && ready_out;
    wire unload = ready_in && valid_reg;

    assign ready_out = ~valid_reg || ready_in;
    assign valid_out = valid_reg;
    assign data_out  = acc_reg;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            acc_reg   <= {DATA_WIDTH{1'b0}};
            valid_reg <= 1'b0;
        end else begin
            if (load && unload) begin
                // simultaneous: replace data and remain valid
                acc_reg   <= acc_reg + data_in;
                // valid_reg stays 1
            end else if (load) begin
                acc_reg   <= acc_reg + data_in;
                valid_reg <= 1'b1;
            end else if (unload) begin
                valid_reg <= 1'b0;
            end
        end
    end

endmodule

// Single-entry skid buffer for backpressure tolerance
`timescale 1ns / 1ps

module skid_buffer #(
    parameter DATA_WIDTH = 8
) (
    input  wire                        clk,
    input  wire                        reset_n,
    input  wire [DATA_WIDTH-1:0]       s_in_data,
    input  wire                        s_in_valid,
    output wire                        s_in_ready,
    output wire [DATA_WIDTH-1:0]       s_out_data,
    output wire                        s_out_valid,
    input  wire                        s_out_ready
);

    reg [DATA_WIDTH-1:0] buf_data;
    reg                  buf_valid;

    wire pass_through = ~buf_valid;

    assign s_in_ready = ~buf_valid || s_out_ready;
    assign s_out_data = buf_valid ? buf_data : s_in_data;
    assign s_out_valid = buf_valid || (s_in_valid && pass_through);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            buf_data  <= {DATA_WIDTH{1'b0}};
            buf_valid <= 1'b0;
        end else begin
            if (s_in_ready && s_in_valid) begin
                if (s_out_ready && buf_valid) begin
                    // simultaneous unload and load: output accepts previous buffer, load new
                    buf_data <= s_in_data;
                    // buf_valid stays 1
                end else if (~s_out_ready && ~buf_valid) begin
                    // store because output not ready
                    buf_data <= s_in_data;
                    buf_valid <= 1'b1;
                end
                // else: pass-through (output ready and buffer empty), no storage needed
            end else if (s_out_ready && buf_valid) begin
                // unload only
                buf_valid <= 1'b0;
            end
        end
    end

endmodule

// Joins two input streams: output valid when both inputs valid, output data = sum (mod 2^DATA_WIDTH)
`timescale 1ns / 1ps

/* verilator lint_off UNUSEDSIGNAL */
module stream_join #(
    parameter DATA_WIDTH = 8
) (
    input  wire                        clk,
    input  wire                        reset_n,
    input  wire [DATA_WIDTH-1:0]       in0_data,
    input  wire                        in0_valid,
    output wire                        in0_ready,
    input  wire [DATA_WIDTH-1:0]       in1_data,
    input  wire                        in1_valid,
    output wire                        in1_ready,
    output wire [DATA_WIDTH-1:0]       out_data,
    output wire                        out_valid,
    input  wire                        out_ready
);

    // No internal state; combinatorial logic
    assign in0_ready = out_ready;
    assign in1_ready = out_ready;
    assign out_valid = in0_valid && in1_valid;
    assign out_data  = in0_data + in1_data;

endmodule
