// Simple pipeline register stage (single flop) for output
`timescale 1ns / 1ps

module stream_stage #(
    parameter DATA_WIDTH = 8
) (
    input  wire                        clk,
    input  wire                        reset_n,
    input  wire [DATA_WIDTH-1:0]       s_in_data,
    input  wire                        s_in_valid,
    output wire                        s_in_ready,
    output wire [DATA_WIDTH-1:0]       s_out_data,
    output wire                        s_out_valid,
    input  wire                        s_out_ready
);

    reg                  pipe_valid;
    reg [DATA_WIDTH-1:0] pipe_data;

    assign s_in_ready = ~pipe_valid || s_out_ready;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            pipe_valid <= 1'b0;
        end else begin
            if (s_in_ready && s_in_valid) begin
                pipe_data  <= s_in_data;
                pipe_valid <= 1'b1;
            end else if (s_out_ready) begin
                pipe_valid <= 1'b0;
            end
        end
    end

    assign s_out_data  = pipe_data;
    assign s_out_valid = pipe_valid;

endmodule

// top module: integration wrapper for dual-stream join with accumulation
`timescale 1ns / 1ps

module top (
    input  wire        clk,
    input  wire        reset_n,
    input  wire [7:0]  in0_data,
    input  wire        in0_valid,
    output wire        in0_ready,
    input  wire [7:0]  in1_data,
    input  wire        in1_valid,
    output wire        in1_ready,
    output wire [7:0]  out_data,
    output wire        out_valid,
    input  wire        out_ready
);
    parameter DATA_WIDTH = 8;

    // Internal wires
    wire [DATA_WIDTH-1:0] in0_buf_data;
    wire                  in0_buf_valid;
    wire                  in0_buf_ready;
    wire [DATA_WIDTH-1:0] in1_buf_data;
    wire                  in1_buf_valid;
    wire                  in1_buf_ready;
    wire [DATA_WIDTH-1:0] join_data;
    wire                  join_valid;
    wire                  join_ready;
    wire [DATA_WIDTH-1:0] accum_data;
    wire                  accum_valid;
    wire                  accum_ready;
    wire [DATA_WIDTH-1:0] out_stage_data;
    wire                  out_stage_valid;
    wire                  out_stage_ready;

    // Instances
    skid_buffer #(.DATA_WIDTH(DATA_WIDTH)) in0_buffer (
        .clk(clk),
        .reset_n(reset_n),
        .s_in_data(in0_data),
        .s_in_valid(in0_valid),
        .s_in_ready(in0_ready),
        .s_out_data(in0_buf_data),
        .s_out_valid(in0_buf_valid),
        .s_out_ready(in0_buf_ready)
    );

    skid_buffer #(.DATA_WIDTH(DATA_WIDTH)) in1_buffer (
        .clk(clk),
        .reset_n(reset_n),
        .s_in_data(in1_data),
        .s_in_valid(in1_valid),
        .s_in_ready(in1_ready),
        .s_out_data(in1_buf_data),
        .s_out_valid(in1_buf_valid),
        .s_out_ready(in1_buf_ready)
    );

    stream_join #(.DATA_WIDTH(DATA_WIDTH)) join_core (
        .clk(clk),
        .reset_n(reset_n),
        .in0_data(in0_buf_data),
        .in0_valid(in0_buf_valid),
        .in0_ready(in0_buf_ready),
        .in1_data(in1_buf_data),
        .in1_valid(in1_buf_valid),
        .in1_ready(in1_buf_ready),
        .out_data(join_data),
        .out_valid(join_valid),
        .out_ready(join_ready)
    );

    accumulator_core #(.DATA_WIDTH(DATA_WIDTH)) accumulator (
        .clk(clk),
        .reset_n(reset_n),
        .data_in(join_data),
        .valid_in(join_valid),
        .ready_out(join_ready),
        .data_out(accum_data),
        .valid_out(accum_valid),
        .ready_in(accum_ready)
    );

    stream_stage #(.DATA_WIDTH(DATA_WIDTH)) out_stage (
        .clk(clk),
        .reset_n(reset_n),
        .s_in_data(accum_data),
        .s_in_valid(accum_valid),
        .s_in_ready(accum_ready),
        .s_out_data(out_stage_data),
        .s_out_valid(out_stage_valid),
        .s_out_ready(out_stage_ready)
    );

    // Output assignments
    assign out_data        = out_stage_data;
    assign out_valid       = out_stage_valid;
    assign out_stage_ready = out_ready;

endmodule

// Self-checking testbench for top module
`timescale 1ns / 1ps

module tb_top;

    reg clk;
    reg reset_n;
    reg [7:0] in0_data;
    reg in0_valid;
    wire in0_ready;
    reg [7:0] in1_data;
    reg in1_valid;
    wire in1_ready;
    wire [7:0] out_data;
    wire out_valid;
    reg out_ready;

    top dut (
        .clk(clk),
        .reset_n(reset_n),
        .in0_data(in0_data),
        .in0_valid(in0_valid),
        .in0_ready(in0_ready),
        .in1_data(in1_data),
        .in1_valid(in1_valid),
        .in1_ready(in1_ready),
        .out_data(out_data),
        .out_valid(out_valid),
        .out_ready(out_ready)
    );

    // Clock generation
    always #5 clk = ~clk;

    // Test variables
    integer test_failed;
    integer timeout_count;
    reg [7:0] expected_acc;
    reg [7:0] in0_seq [0:4];
    reg [7:0] in1_seq [0:4];
    reg [7:0] out_seq [0:4];
    integer i;
    reg last_out_valid;
    reg wait_for_new;

    initial begin
        clk = 0;
        reset_n = 0;
        in0_data = 0;
        in0_valid = 0;
        in1_data = 0;
        in1_valid = 0;
        out_ready = 0;
        test_failed = 0;

        // Initialize sequences
        in0_seq[0] = 8'd10; in0_seq[1] = 8'd20; in0_seq[2] = 8'd30; in0_seq[3] = 8'd40; in0_seq[4] = 8'd50;
        in1_seq[0] = 8'd1; in1_seq[1] = 8'd2; in1_seq[2] = 8'd3; in1_seq[3] = 8'd4; in1_seq[4] = 8'd5;
        expected_acc = 0;

        // Reset
        #10 reset_n = 1;
        #10;

        // Test 1: Basic back-to-back transfers
        $display("Starting basic test...");
        out_ready = 1;
        last_out_valid = 0;
        for (i = 0; i < 5; i = i + 1) begin
            // Drive inputs on negedge
            @(negedge clk);
            in0_data = in0_seq[i];
            in0_valid = 1;
            in1_data = in1_seq[i];
            in1_valid = 1;
            // Wait for rising edge on out_valid (new output)
            timeout_count = 0;
            wait_for_new = 1;
            while (wait_for_new) begin
                @(posedge clk);
                timeout_count = timeout_count + 1;
                if (timeout_count > 100) begin
                    $display("TEST_FAIL: Timeout waiting for out_valid");
                    test_failed = 1;
                    $finish;
                end
                if (out_valid && ~last_out_valid) begin
                    wait_for_new = 0;
                end
                last_out_valid = out_valid;
                #1;
            end
            // Check output on negedge after valid
            @(negedge clk);
            expected_acc = expected_acc + (in0_seq[i] + in1_seq[i]);
            if (out_data !== expected_acc) begin
                $display("TEST_FAIL: Mismatch at transfer %0d, expected %0d, got %0d", i, expected_acc, out_data);
                test_failed = 1;
            end
            // Deassert valid after handshake
            @(negedge clk);
            in0_valid = 0;
            in1_valid = 0;
        end
        // Wait for pipeline to flush
        repeat (5) @(posedge clk);
        #1;

        // Test 2: Backpressure
        $display("Starting backpressure test...");
        out_ready = 0;
        last_out_valid = 0;
        // Send one transfer
        @(negedge clk);
        in0_data = 8'd100;
        in0_valid = 1;
        in1_data = 8'd200;
        in1_valid = 1;
        // Wait a few cycles with out_ready low
        repeat (3) @(posedge clk);
        // Assert out_ready
        @(negedge clk);
        out_ready = 1;
        // Wait for new output (rising edge)
        timeout_count = 0;
        wait_for_new = 1;
        while (wait_for_new) begin
            @(posedge clk);
            timeout_count = timeout_count + 1;
            if (timeout_count > 100) begin
                $display("TEST_FAIL: Timeout during backpressure test");
                test_failed = 1;
                $finish;
            end
            if (out_valid && ~last_out_valid) begin
                wait_for_new = 0;
            end
            last_out_valid = out_valid;
            #1;
        end
        @(negedge clk);
        expected_acc = expected_acc + (8'd100 + 8'd200);
        if (out_data !== expected_acc) begin
            $display("TEST_FAIL: Backpressure mismatch, expected %0d, got %0d", expected_acc, out_data);
            test_failed = 1;
        end
        @(negedge clk);
        in0_valid = 0;
        in1_valid = 0;
        out_ready = 0;
        // Flush
        repeat (5) @(posedge clk);
        #1;

        // Test 3: Reset verification
        $display("Starting reset test...");
        @(negedge clk);
        reset_n = 0;
        #10;
        reset_n = 1;
        #10;
        last_out_valid = 0;
        // Send a new sample
        @(negedge clk);
        in0_data = 8'd1;
        in0_valid = 1;
        in1_data = 8'd2;
        in1_valid = 1;
        out_ready = 1;
        timeout_count = 0;
        wait_for_new = 1;
        while (wait_for_new) begin
            @(posedge clk);
            timeout_count = timeout_count + 1;
            if (timeout_count > 100) begin
                $display("TEST_FAIL: Timeout after reset");
                test_failed = 1;
                $finish;
            end
            if (out_valid && ~last_out_valid) begin
                wait_for_new = 0;
            end
            last_out_valid = out_valid;
            #1;
        end
        @(negedge clk);
        if (out_data !== 8'd3) begin // 1+2=3, accumulator should be 0 after reset
            $display("TEST_FAIL: After reset expected 3, got %0d", out_data);
            test_failed = 1;
        end
        @(negedge clk);
        in0_valid = 0;
        in1_valid = 0;
        out_ready = 0;

        // Final result
        #50;
        if (test_failed) begin
            $display("TEST_FAIL");
        end else begin
            $display("TEST_PASS");
        end
        $finish;
    end

endmodule

// counter_core.v - Synchronous 8-bit counter with active-low reset
// System-HIS v1.2 compliant

module counter_core #(
    parameter DATA_WIDTH = 8
)(
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  inc,
    output wire [DATA_WIDTH-1:0] count
);

    reg [DATA_WIDTH-1:0] event_count_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            event_count_reg <= {DATA_WIDTH{1'b0}};
        end else if (inc) begin
            event_count_reg <= event_count_reg + 1'b1;
        end
    end

    assign count = event_count_reg;

endmodule

// event_gate.v - Combinational event gate
// System-HIS v1.2 compliant

module event_gate (
    input  wire clk,
    input  wire rst_n,
    input  wire event_in,
    output wire gated_event
);

    // Combinational pass-through gate
    // Latency: 0 cycles, throughput: combinational
    assign gated_event = event_in;

endmodule

// top.v - Integration wrapper for 8-bit event counter
// System-HIS v1.2 compliant

module top #(
    parameter DATA_WIDTH = 8
)(
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  event_in,
    output wire [DATA_WIDTH-1:0] count_out
);

    wire gated_event_wire;

    event_gate u_event_gate (
        .clk         (clk),
        .rst_n       (rst_n),
        .event_in    (event_in),
        .gated_event (gated_event_wire)
    );

    counter_core #(
        .DATA_WIDTH (DATA_WIDTH)
    ) u_counter (
        .clk   (clk),
        .rst_n (rst_n),
        .inc   (gated_event_wire),
        .count (count_out)
    );

endmodule

// tb_top.v - Self-checking testbench for top event counter
// Compiles with: iverilog -g2012

`timescale 1ns / 1ps

module tb_top;

    parameter DATA_WIDTH = 8;
    parameter CLK_PERIOD = 10;

    reg                  clk;
    reg                  rst_n;
    reg                  event_in;
    wire [DATA_WIDTH-1:0] count_out;

    integer cycle_cnt;
    integer err_cnt;
    integer i;

    // DUT instantiation
    top #(
        .DATA_WIDTH (DATA_WIDTH)
    ) dut (
        .clk       (clk),
        .rst_n     (rst_n),
        .event_in  (event_in),
        .count_out (count_out)
    );

    // Clock generation
    initial begin
        clk = 1'b0;
    end
    always #(CLK_PERIOD/2) clk = ~clk;

    // Monitor for timeout
    always @(posedge clk) begin
        cycle_cnt <= cycle_cnt + 1;
        if (cycle_cnt > 500) begin
            $display("TEST_FAIL: Simulation timeout at cycle %0d", cycle_cnt);
            $finish;
        end
    end

    // Helper task: send a single event pulse for one clock cycle
    task send_event_pulse;
        begin
            @(negedge clk);
            event_in = 1'b1;
            @(negedge clk);
            event_in = 1'b0;
        end
    endtask

    // Helper task: check count value
    task check_count;
        input [DATA_WIDTH-1:0] expected;
        begin
            @(negedge clk);
            if (count_out !== expected) begin
                $display("TEST_FAIL: Expected count %0d, got %0d at cycle %0d",
                         expected, count_out, cycle_cnt);
                err_cnt = err_cnt + 1;
            end else begin
                $display("INFO: Count check passed: %0d == %0d", count_out, expected);
            end
        end
    endtask

    // Main test sequence
    initial begin
        $display("=== Event Counter Testbench Start ===");
        cycle_cnt = 0;
        err_cnt   = 0;
        rst_n     = 1'b0;
        event_in  = 1'b0;

        // Hold reset for a few cycles
        repeat (5) @(posedge clk);
        @(negedge clk);
        rst_n = 1'b1;

        // Wait a cycle after reset release
        repeat (2) @(posedge clk);

        // ============================================
        // Scenario 1: basic_count - Send 5 pulses, verify count is 5
        // ============================================
        $display("--- Scenario 1: basic_count ---");

        for (i = 0; i < 5; i = i + 1) begin
            send_event_pulse;
        end

        // Allow one cycle for the last increment to settle
        @(negedge clk);

        check_count(8'd5);

        // ============================================
        // Scenario 2: reset_test - Assert reset, verify count is 0
        // ============================================
        $display("--- Scenario 2: reset_test ---");

        // Assert reset synchronously
        @(negedge clk);
        rst_n = 1'b0;

        // Wait for reset to take effect
        repeat (3) @(posedge clk);
        @(negedge clk);

        check_count(8'd0);

        // Release reset
        rst_n = 1'b1;
        repeat (2) @(posedge clk);

        // Verify counter still at 0 after reset release
        check_count(8'd0);

        // ============================================
        // Additional: Send 3 more pulses after reset
        // ============================================
        $display("--- Additional: 3 pulses after reset ---");

        for (i = 0; i < 3; i = i + 1) begin
            send_event_pulse;
        end

        @(negedge clk);
        check_count(8'd3);

        // ============================================
        // Final result
        // ============================================
        repeat (3) @(posedge clk);

        if (err_cnt == 0) begin
            $display("=== TEST_PASS ===");
        end else begin
            $display("=== TEST_FAIL: %0d errors detected ===", err_cnt);
        end

        $finish;
    end

endmodule

